import os
import json
from pathlib import Path

# First, let's check what policy documents are available
policy_files = []
for file in os.listdir('.'):
    if 'policy' in file.lower() and file.endswith(('.txt', '.json', '.md', '.pdf')):
        policy_files.append(file)

print("Found policy files:", policy_files)

# Read each policy document
policies = {}
for file in policy_files:
    try:
        if file.endswith('.json'):
            with open(file, 'r') as f:
                policies[file] = json.load(f)
        else:
            with open(file, 'r', encoding='utf-8') as f:
                policies[file] = f.read()
        print(f"Successfully read {file}")
    except Exception as e:
        print(f"Error reading {file}: {e}")

# Display basic info about each policy
print("\n=== Policy Documents Summary ===")
for filename, content in policies.items():
    if isinstance(content, dict):
        print(f"\n{filename}: JSON document with keys: {list(content.keys())}")
        # Check for metadata that might indicate authority
        if 'version' in content:
            print(f"  Version: {content['version']}")
        if 'effective_date' in content:
            print(f"  Effective Date: {content['effective_date']}")
        if 'authority' in content:
            print(f"  Authority: {content['authority']}")
    else:
        print(f"\n{filename}: Text document ({len(content)} characters)")
        # Look for authority indicators in text
        lines = content.split('\n')
        for i, line in enumerate(lines[:10]):  # Check first 10 lines
            line_lower = line.lower()
            if any(keyword in line_lower for keyword in ['authoritative', 'official', 'master', 'primary', 'supersedes']):
                print(f"  Authority indicator found: {line.strip()}")
            if 'version' in line_lower or 'effective' in line_lower:
                print(f"  Version/Date info: {line.strip()}")
